def test_continuation_disabled_for_the_default_harness_profile(smol_agent):
    # ``codx-junior`` is the AGILE tier (the default): it stops at the tool limit
    # and delivers a partial increment with its own summary.
    assert smol_agent._continuation_enabled(
        config={}, orchestration_info=None, profile_names=["codx-junior"]
    ) is False
    assert smol_agent._continuation_enabled(
        config={}, orchestration_info=None, profile_names=["@codx-junior", "x"]
    ) is False


def test_continuation_enabled_for_the_max_effort_profile(smol_agent):
    # ``codx-junior-max`` is the ONLY tier that inherits the old "the harness
    # resolves itself" behaviour.
    assert smol_agent._continuation_enabled(
        config={}, orchestration_info=None, profile_names=["codx-junior-max"]
    ) is True
    assert smol_agent._continuation_enabled(
        config={}, orchestration_info=None, profile_names=["@codx-junior-max"]
    ) is True

